-- ============================================================
-- KOJOH: seed for "The Diwali Discount Trap: E-commerce Appliance Orders, India"  (slug: diwali-discount-trap-fy2526)
-- Safe to run more than once. Run AFTER schema-marketplace.sql and schema-preview.sql.
-- Also create the storage folder datasets/diwali-discount-trap-fy2526/ and upload the files in
-- storage_upload/diwali-discount-trap-fy2526/ (csv, xlsx, dictionary, story).
-- ============================================================

insert into public.datasets (folder_id, slug, title, short_description, long_description,
                              price, is_free, difficulty, storage_path)
select f.id, 'diwali-discount-trap-fy2526', 'The Diwali Discount Trap: E-commerce Appliance Orders, India',
  'A year of messy order exports from a fictional Indian appliance brand selling on Amazon, Flipkart, Meesho and its own site: 14,701 order lines, 41 columns, 20 listing managers, 40 SKUs. Clean it, then settle the argument management can''t: why the biggest sales month lost money, which discount depth stops paying, and why the customers who paid full price were worth several times more than the ones who came in on sale.',
  'Nivaas Home is a direct-to-consumer kitchen and home appliance brand based in Gurugram. It sells six product families (air fryers, mixer grinders, electric kettles, induction cooktops, vacuum cleaners and room heaters, forty SKUs in all) through four channels: Amazon.in, Flipkart, Meesho and its own website. Twenty listing managers each own one category on one channel: they set prices, pick discounts, run ads and answer for the numbers. Every order line lands in the company''s order management export, keyed in or pasted together from four different marketplace dashboards. The financial year just closed on 31 March 2026, and the founders are arguing about October. The Sales Head is pointing at the revenue chart. For Diwali the company ran its biggest sale ever, **124.5 lakh of orders booked in October, 2.3 times September''s 53.7 lakh**. The listing manager who drove the most delivered sales that month and that year, **Ritesh Rawat** (Air Fryer, Amazon.in), is the obvious pick for the annual bonus. Nobody questions that October was the best month. It says so right there on the dashboard. The Finance Head has done the arithmetic differently. After the cost of the goods, marketplace fees, shipping, packaging, ad spend and the cost of everything that came back, she says October did not make money. It lost money, in a year in which every other month did. And the person with the biggest sales number ranks near the bottom on the money they actually left in the business.',
  99.00, false, 'hard', 'diwali-discount-trap-fy2526'
from public.folders f
where f.slug = 'data-analyst'
on conflict (slug) do nothing;

insert into public.dataset_job_titles (dataset_id, job_title_id)
select d.id, jt.id from public.datasets d, public.job_titles jt
where d.slug = 'diwali-discount-trap-fy2526' and jt.name = 'Data Analyst'
on conflict do nothing;

insert into public.dataset_tags (dataset_id, tag_id)
select d.id, t.id from public.datasets d, public.tags t
where d.slug = 'diwali-discount-trap-fy2526' and t.name in ('Python', 'SQL', 'Excel', 'Power BI', 'E-commerce')
on conflict do nothing;

insert into public.dataset_schema (dataset_id, column_name, column_type, description, sort_order)
select d.id, col.column_name, col.column_type, col.description, col.sort_order
from public.datasets d
cross join (values
  ('Order ID', 'text', 'Order reference, e.g. `NH257758`. Not unique: about 190 orders were pasted in twice and carry the same ID.', 1),
  ('Order Date', 'text (mixed date formats)', 'When the customer placed the order. Five mixed formats (see the note below).', 2),
  ('Ship Date', 'text (mixed date formats)', 'When the parcel left the warehouse. Same five formats. Blank for Cancelled orders.', 3),
  ('Delivery Date', 'text (mixed date formats)', 'When the courier delivered. Same five formats. Blank for Cancelled and RTO orders. A few rows fall before the order date.', 4),
  ('Month', 'text', 'Sales month label, e.g. `Oct-25`. **~40% blank.** Derive it from Order Date instead.', 5),
  ('Marketplace', 'text', 'Amazon.in, Flipkart, Own Website or Meesho. ~5 spellings each: `AMZ`, `Amazon India`, `FK`, `D2C Site`, `Website`.', 6),
  ('Fulfilment', 'text', 'FBA, Easy Ship, Smart Fulfilment, Seller Fulfilled or Self Ship. Clean.', 7),
  ('SKU', 'text', 'Stock code, e.g. `NH-AF-402`. ~3% lowercased.', 8),
  ('Product Name', 'text', 'Product name. Clean.', 9),
  ('Category', 'text', 'Air Fryer, Mixer Grinder, Electric Kettle, Induction Cooktop, Vacuum Cleaner or Room Heater. Five spellings each: `AirFryer`, `MG`, `E-Kettle`, `Induction`, `Vac Cleaner`.', 10),
  ('Listing Manager', 'text', 'Free-text name of the person who owns the category on that marketplace. **The key trap.** Each of 20 people appears under ~8 spellings: `Anil Sood`, `anil sood`, `ANIL SOOD`, `A. Sood`, `Anil S`, `Sood, Anil`, double spaces, trailing spaces.', 11),
  ('Emp Code', 'text', 'Employee code, e.g. `NH2001`. Better key than the name, but ~5% blank, ~2.5% lowercase, ~2% typo''d (`NH02001`). Don''t trust either field alone.', 12),
  ('Campaign', 'text', '`Diwali Dhamaka`, `Independence Day Sale`, `Republic Day Sale`, `Summer Fest` or none. ~8% blank or upper-cased by mistake.', 13),
  ('Coupon Code', 'text', 'Promo code used, if any. Mostly blank.', 14),
  ('MRP', 'text (mixed currency formats)', 'Printed maximum retail price per unit, GST included. Money text in several formats.', 15),
  ('Discount %', 'text', 'Discount off MRP. `40%`, `40.00`, `0.4000`, `40.0 %`, `40`.', 16),
  ('Selling Price', 'text (mixed currency formats)', 'What the customer paid per unit, GST included. Money text in several formats. A few negative values; ~10 rows where MRP and Selling Price are swapped.', 17),
  ('Quantity', 'text', 'Units on the line. `2`, `2 pcs`, `2 units`, `Two`. A handful of zeros.', 18),
  ('Order Value', 'text (mixed currency formats)', 'Quantity x Selling Price, GST included. Money text in several formats.', 19),
  ('Unit COGS', 'text (mixed currency formats)', 'Landed product cost per unit. ~2.5% blank.', 20),
  ('Marketplace Fee', 'text (mixed currency formats)', 'Commission and closing fees charged for the order. ~3% blank.', 21),
  ('Shipping Cost', 'text (mixed currency formats)', 'Courier cost to deliver (blank or zero on cancellations). ~4% blank.', 22),
  ('Packaging Cost', 'text (mixed currency formats)', 'Box, filler and labels. ~6% blank.', 23),
  ('Ad Spend', 'text (mixed currency formats)', 'Advertising cost attributed to the order. Blank vs `0` on unadvertised orders.', 24),
  ('Payment Mode', 'text', 'UPI, Card, COD, NetBanking or EMI. ~5 spellings each: `Cash on Delivery`, `CC`, `No Cost EMI`.', 25),
  ('Order Status', 'text', 'Delivered, Returned, Cancelled or RTO (return to origin). **~25 spellings** of four outcomes: `Dlvrd`, `Closed - Delivered`, `Customer Return`, `Canceled`, `Undelivered - RTO`.', 26),
  ('Return Reason', 'text', 'Why the customer sent it back. Blank unless Returned.', 27),
  ('Refund Amount', 'text (mixed currency formats)', 'Money returned to the customer. A few rows exceed the order value.', 28),
  ('Return Pickup Cost', 'text (mixed currency formats)', 'Cost of the reverse pickup or the RTO leg. Blank unless Returned or RTO.', 29),
  ('Customer ID', 'text', 'Customer reference. ~4% blank.', 30),
  ('Customer Name', 'text (free-text, many spellings)', 'Free-text name. Each customer appears under several spellings.', 31),
  ('Customer Type', 'text', 'New or Repeat, as flagged by the system. ~5% wrong; ~12% lowercase.', 32),
  ('City', 'text', 'Delivery city. Case noise and abbreviations.', 33),
  ('State', 'text', 'Delivery state. Case noise and abbreviations.', 34),
  ('Pincode', 'text', 'Delivery pincode. `226010`, `226010.0` or `226 010`.', 35),
  ('Acquisition Channel', 'text', 'Organic, Sponsored Ads, Deal Page, Paid Social, Influencer or Email/WhatsApp. ~4 spellings each.', 36),
  ('Courier', 'text', 'Delhivery, Ekart, Amazon Logistics, Ecom Express, Xpressbees, Blue Dart or Shadowfax. Clean.', 37),
  ('Warehouse', 'text', 'Gurugram FC, Bhiwandi FC or Bengaluru FC. Clean.', 38),
  ('Review Rating', 'text', 'Star rating, 1 to 5. Blank on ~62% of Delivered and Returned lines.', 39),
  ('Review Comment', 'text', 'Short review text. Mostly blank.', 40),
  ('Remarks', 'text', 'Free-text note from the account team. Mostly blank.', 41)
) as col(column_name, column_type, description, sort_order)
where d.slug = 'diwali-discount-trap-fy2526'
and not exists (select 1 from public.dataset_schema s where s.dataset_id = d.id);

alter table public.datasets add column if not exists preview_rows jsonb;
alter table public.datasets add column if not exists locked_preview jsonb;

update public.datasets
set preview_rows = $prev${"columns": ["Order ID", "Order Date", "Ship Date", "Delivery Date", "Month", "Marketplace", "Fulfilment", "SKU", "Product Name", "Category", "Listing Manager", "Emp Code", "Campaign", "Coupon Code", "MRP", "Discount %", "Selling Price", "Quantity", "Order Value", "Unit COGS", "Marketplace Fee", "Shipping Cost", "Packaging Cost", "Ad Spend", "Payment Mode", "Order Status", "Return Reason", "Refund Amount", "Return Pickup Cost", "Customer ID", "Customer Name", "Customer Type", "City", "State", "Pincode", "Acquisition Channel", "Courier", "Warehouse", "Review Rating", "Review Comment", "Remarks"], "rows": [["NH258746", "06/07/2025", "8 Jul 2025", "45851", "Jul-25", "Flipkart.com", "Smart Fulfilment", "NH-AF-301", "CrispAir 3L Digital", "Air Fryer", "KAVYA MENON", "NH2002", "None", "", "5,990", "27.9 %", "4319.00", "1", "4319", "  2546  ", "561", "Rs 102", "39", "", "upi", "delivered", "", "", "", "C118690", "Mohit Pandey", "New", "LUDHIANA", "Punjab", "141376", "Organic", "Ekart", "Gurugram FC", "", "", "gift wrap"], ["NH291018", "46082", "2 Mar 2026", "5 Mar 2026", "Mar-26", "Own Website", "Self Ship", "NH-MG-060", "Masala Maestro 600W Duo", "Mixer Grinder", "farhan qureshi", "NH2006", "None", "", "3990", "16.07", "3349", "1", "3,349", "1481", "84", "Rs 98", "40", "0", "Credit Card", "Completed", "", "", "", "C176468", "Vikram Naidu", "Repeat", "Ludhiana", "Punjab", "141857", "Organic", "Blue Dart", "Gurugram FC", "", "", "address corrected"], ["NH264388", "23-08-25", "26-08-25", "28-08-25", "Aug-25", "Amazon.in", "Easy Ship", "NH-MG-075J", "Masala Maestro 750W Juicer", "Mixer Grinder", "A. Sood", "NH2004", "None", "NH5OFF", "Rs 5,990", "26", "4419", "1", "4,419", "2,189", "574", "75.00", "33", "  528  ", "NetBanking", "Dlvrd", "", "0", "", "C129939", "Anita Pandey", "New", "Lucknow ", "uttar pradesh", "226830.0", "Sponsored Ads", "Delhivery", "Gurugram FC", "5", "Works well", "address corrected"], ["NH294064", "2026-03-31", "02/04/2026", "08/04/2026", "Mar-26", "Amazon India", "FBA", "NH-VC-CR3", "DustPilot Car Vac", "Vacuum Cleaner", "Lakshmi Raman", "NH2015", "None", "", "2990", "19%", "2419.00", "2", "4838", "Rs 1,124", "  677  ", "  164  ", "₹28", "", "Upi", "Delivered", "", "", "", "C186436", "Rohan  Verma", "New", "Delhi", "Delhi", "110621", "Organic", "Delhivery", "Gurugram FC", "4", "Good value", ""], ["NH293254", "23/03/2026", "24 Mar 2026", "27-03-26", "Mar-26", "Own Website", "Self Ship", "NH-AF-352", "CrispAir 3.5L Mini", "Air Fryer", "Harpreet  Gill", "NH2003", "", "FESTIVE15", "Rs 6,990", "18.5 %", "5699", "1", "5,699", "2,985", "  142  ", "Rs 119", "38", "", "PhonePe UPI", "Closed - Delivered", "", "0", "", "C178771", "Sandeep M", "Repeat", "BEN", "KARNATAKA", "560729", "Organic", "Delhivery", "Bengaluru FC", "5", "", "urgent"]], "total_rows": 14891}$prev$::jsonb,
    locked_preview = $lock${"summary": "A full four phase analyst project built on 14,891 rows across 41 columns of messy e-commerce order exports from a fictional Indian appliance brand. You clean it, you query it, you build a two page dashboard on it, then you write the recommendation that explains why the biggest sales month lost money.", "phases": [{"title": "Phase 1, Python: Clean the Data", "blurb": "Turn the raw order export into a trustworthy table. Nothing later works until this does.", "count": 8, "sample": ["Load the raw CSV/XLSX and profile it: row count, column count, null counts per column, and a written note on the five things that look most wrong before you touch anything.", "Remove duplicate order entries (~190 of them). State your de-duplication rule and how many genuine order lines remain."]}, {"title": "Phase 2, SQL: Answer the Business Questions", "blurb": "Settle the arguments management cannot settle themselves, with evidence.", "count": 12, "sample": ["Rank the 20 listing managers by delivered GMV (sum of order_value on Delivered lines). Return name, category, marketplace, GMV and rank.", "Using the contribution-margin convention above (or your own, clearly stated), compute revenue (booked order value) and contribution margin per month. Return the months where revenue rose but contribution fell versus the previous month, using LAG()."]}, {"title": "Phase 3a, Dashboard Page 1: Order Lookup", "blurb": "Type an Order ID, get everything about that product, that price and that profit.", "count": 5, "sample": ["Build a search box that takes an Order ID and shows the full story of that one line: product and listing manager, the price chain (MRP -> discount -> selling price -> ex-GST revenue), the cost stack (COGS, fee, shipping, packaging, ad spend, return costs) and the resulting contribution as a waterfall.", "On the same screen show customer context: new vs repeat, city and state, acquisition channel, payment mode, review rating and comment, and any remarks."]}, {"title": "Phase 3b, Dashboard Page 2: Analytics", "blurb": "The analytics page management actually lives in.", "count": 10, "sample": ["Build a listing-manager leaderboard showing GMV, contribution and contribution margin % side by side, so 'best' is never reduced to one number the viewer can't question.", "Add a monthly trend panel showing booked revenue and contribution together, so a viewer can see the month where they move in opposite directions."]}, {"title": "Phase 4, Documentation", "blurb": "Write the recommendation you would actually hand a founder.", "count": 1, "sample": ["Write a short project write-up (any format: Word, PDF, Notion, a README) with three sections: (1) **Process Flow**: how you went from the raw export to cleaned data to SQL answers to your dashboard, including the decisions you made, especially how you resolved listing-manager and customer identity; (2) **Key Discoveries**: your top 3-5 findings, stated the way a decision-maker wants to hear them, not as code output; (3) **Future Growth Recommendations**: at least 3 concrete, data-backed recommendations for what Nivaas Home should do before next Diwali. This is the deliverable a hiring manager would actually read, so treat it that way."]}, {"title": "Stretch ideas (optional)", "blurb": "Optional extras, a personal pick of 3 for every buyer.", "count": 6, "sample": ["Simulate a 30% discount cap on Air Fryers and Induction Cooktops during the Diwali peak. State your assumption about how much volume you would lose, then estimate the contribution you would have made instead.", "Test the pull-forward theory: did November and December volume dip because Diwali buyers had already bought? Compare against the other non-sale months and be honest about what the data can and cannot prove."]}], "premium_count": 5, "total_tasks": 42}$lock$::jsonb
where slug = 'diwali-discount-trap-fy2526';

